/* @lc app=leetcode id=3334 lang=kotlin */ class Solution { fun g(a: Long, b: Long): Long = if (b == 0L) a else g(b, a % b) fun sc(a: List<Int>): Long = if (a.isEmpty()) 0L else a.fold(0L) { x, y -> g(x, y.toLong()) } * a.fold(1L) { l, x -> l / g(l, x.toLong()) * x } fun maxScore(nums: IntArray): Long = nums.toList().let { l -> maxOf(sc(l), l.indices.maxOf { i -> sc(l.filterIndexed { j, _ -> j != i }) }) } }